/* eslint react/no-multi-comp: 0, react/prop-types: 0 */

import React, { useState } from "react";
import { Button, Modal, ModalHeader, ModalBody, ModalFooter, Col, Form, FormGroup, Label, Input } from "reactstrap";

// redux
import { connect } from "react-redux";
import { handleExceptionMannually } from "../actions/utils";
import { updateVisaIssuerTransactions, updateVisaAcquirerTransactions } from "../actions/filesets";

const ManuallResolutionModal = ({
	handleExceptionMannually,
	updateVisaIssuerTransactions,
	updateVisaAcquirerTransactions,
	updateTransactionType,
	className,
	openModal,
	transactionData,
	transactionDate,
}) => {
	const [ modal, setModal ] = useState(false);
	const [ postillionRRN, setPostillionRRN ] = useState("");
	const [ lcyAmount, setLcyAmount ] = useState("");
	const [ isError, setError ] = useState(false);

	const toggle = () => setModal(!modal);

	const handleSubmit = () => {
		// handle form submit
		let resolvedTransactionData = {};
		resolvedTransactionData.id = transactionData.id;
		resolvedTransactionData.postilionRrn = postillionRRN;
		resolvedTransactionData.flexCubeLcyAmount = lcyAmount;

		// tests form for error.
		if (
			(resolvedTransactionData.postilionRrn && resolvedTransactionData.flexCubeLcyAmount) ||
			(!postillionRRN && !lcyAmount)
		) {
			setError(true);
			return;
		}

		if (updateTransactionType === "issuer") {
			updateVisaIssuerTransactions(resolvedTransactionData, transactionDate); // call VisaIssuerTransactions update
		} else if (updateTransactionType === "acquirer") {
			updateVisaAcquirerTransactions(resolvedTransactionData, transactionDate); // call VisaAcquirerTransactions update
		}
		handleExceptionMannually(); // calls the handle Exception Mannually action creator
		handleReset(); // clears all errors and form fields
	};

	const handleReset = () => {
		// Reset form if any errors.
		setError(false);
		setPostillionRRN("");
		setLcyAmount("");
	};

	return (
		<div>
			{/* <Button color="danger" onClick={toggle}>{buttonLabel}</Button> */}
			<Modal isOpen={openModal} toggle={toggle} className={className}>
				<ModalHeader>MANUAL RESOLUTION FORM</ModalHeader>

				<ModalBody>
					<article className='d-flex flex-column'>
						<article className={"d-flex justify-content-between my-2"}>
							<h6>ARN:</h6>
							<span>{transactionData ? transactionData.acquirerReferenceNumber : ""}</span>
						</article>

						<article className={"d-flex justify-content-between my-2"}>
							<h6>MASKED PAN:</h6>
							<span>{transactionData ? transactionData.maskedPan : ""}</span>
						</article>

						<article className={"d-flex justify-content-between my-2"}>
							<h6>SETTLEMENT AMOUNT:</h6>
							<span>{transactionData ? transactionData.settlementAmount : ""}</span>
						</article>

						<article className={"d-flex justify-content-between my-2"}>
							<h6>TRANSACTION DATE:</h6>
							<span>
								{transactionData ? transactionData.txnDateLocal ? (
									transactionData.txnDateLocal[0] +
									"-" +
									transactionData.txnDateLocal[1] +
									"-" +
									transactionData.txnDateLocal[2]
								) : (
									""
								) : (
									""
								)}
							</span>
						</article>

						<article className={"d-flex justify-content-between my-2"}>
							<h6>PRODUCT:</h6>
							<span>{transactionData ? transactionData.product : ""}</span>
						</article>
					</article>

					<Form>
						<h6 className={"text-danger"}>
							{isError && (
								<React.Fragment>
									Please enter either postilionRrn or flexCube Lcy Amount. <br />Click Reset And Try
									Again!
								</React.Fragment>
							)}
						</h6>
						{transactionData ? transactionData.postilionRrn === null && //(transactionData.id  && transactionData.name ? null : true) : ""
						transactionData.flexCubeLcyAmt === null ? (
							<FormGroup row>
								<Label for='postillionRRN' sm={4}>
									POSTILLION RRN:
								</Label>
								<Col sm={8}>
									<Input
										type='text'
										name='postillionRRN'
										id='postillionRRN'
										onChange={(e) => setPostillionRRN(e.target.value)}
										placeholder={"Enter correct Postillion RRN"}
										value={postillionRRN}
									/>
								</Col>
							</FormGroup>
						) : (
							<FormGroup row>
								<Label for='lcyAmount' sm={4}>
									LCY AMOUNT:
								</Label>
								<Col sm={8}>
									<Input
										type='text'
										name='lcyAmount'
										id='lcyAmount'
										onChange={(e) => setLcyAmount(e.target.value)}
										placeholder={"Enter correct Lcy Amount"}
										value={lcyAmount}
									/>
								</Col>
							</FormGroup>
						) : null}
					</Form>
				</ModalBody>

				<ModalFooter>
					<div className={"d-flex justify-content-end align-items-center w-100"}>
						{isError && (
							<Button className={"mx-2"} type='button' color='warning' onClick={handleReset}>
								Reset
							</Button>
						)}
						<div className={"justify-content-end"}>
							<Button type='button' color='success' onClick={handleSubmit}>
								Submit
							</Button>{" "}
							<Button color='danger' onClick={handleExceptionMannually}>
								Cancel
							</Button>
						</div>
					</div>
				</ModalFooter>
			</Modal>
		</div>
	);
};

export default connect(null, {
	handleExceptionMannually,
	updateVisaIssuerTransactions,
	updateVisaAcquirerTransactions,
})(ManuallResolutionModal);
