import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";

import React, { Component } from "react";
import { FormattedMessage } from "react-intl";
import Pagination2 from "react-js-pagination";
import Loader from "react-loader-spinner";
import { connect } from "react-redux";
import { Alert, Button, Card, CardBody, CardGroup, CardHeader, Col, Input, Row, Table as Table2 } from "reactstrap";
import { bindActionCreators } from "redux";

import { downloadVisaAcquirerCsv, fetchVisaAcquirerTransactions } from "../../../../actions/filesets";
import ManuallResolutionModal from "../../../../components/Modal";
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import Widget04 from "../../../../Utils/Widgets04";

// import AddFileSet from './addFileSet';
// import UpdateFileSet from './updateFileSet';

// components
class VisaAcquirerTransactions extends Component {
	constructor (props) {
		super(props);
		this.state = {
			modal            : false,
			activePage       : 1,
			manualResolution : false,
			selectedItem     : {},
			dataType         : "ALL",
			selectedCode     : "",
		};
	}

	static getDerivedStateFromProps (props, state) {
		if (props.manualResolution !== state.manualResolution) {
			return {
				manualResolution : props.manualResolution,
				selectedItem     : props.selectedItem,
			};
		}

		if (props.match.params.page !== state.activePage) {
			return {
				activePage : parseInt(props.match.params.page),
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchVisaAcquirerTransactions(
			this.props.match.params.date,
			this.props.match.params.searchBy,
			this.props.match.params.page - 1,
		);
	}

	componentDidUpdate (prevProps) {
		console.log("THE PROPS", this.props);
		if (this.props.selectedAffiliateCode !== prevProps.selectedAffiliateCode) {
			this.props.fetchVisaAcquirerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}

		if (this.props.match.params.page !== prevProps.match.params.page) {
			this.props.fetchVisaAcquirerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}

		if (this.props.match.params.searchBy !== prevProps.match.params.searchBy) {
			this.props.fetchVisaAcquirerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.fetchVisaAcquirerTransactions(
				this.props.match.params.date,
				this.props.match.params.searchBy,
				this.props.match.params.page - 1,
			);
		}
	}

	handlePageChange = (pageNumber) => {
		this.props.history.push(
			`/visa/settlement/acquirer/${this.props.match.params.date}/transactions/${this.props.match.params
				.searchBy}/${pageNumber}`,
		);
		this.setState({ activePage: pageNumber });
	};

	downloadAcquirerTransactions (date) {
		this.props.downloadVisaAcquirerCsv(date);
	}

	createSelectItems = (selectOptions) => {
		let items = [];
		for (let i = 0; i < selectOptions.length; i++) {
			items.push(<option key={i}>{selectOptions[i]}</option>);
		}
		return items;
	};

	handleSelect = (event) => {
		this.props.history.push(
			`/visa/settlement/acquirer/${this.props.match.params.date}/transactions/${event.target.value}/${this.props
				.match.params.page}`,
		);
		this.setState({
			searchBy : event.target.value,
		});
	};

	render () {
		const VisaIssuerTransactionHeader = [
			"Action",
			"Sre",
			"Bat Number",
			"X MIT Local Date",
			"Time",
			"Card Number",
			"Retrieval Ref Number",
			"Trace Number",
			"Issuer Id",
			"Tran Type",
			"Procss Code",
			"Ent Mod",
			"Reas Code",
			"Cn Stp",
			"Rsp Cd",
			"Transaction Amount",
			"Transaction Currency",
			"Settlement Amount",
			"Settlement Amount Sign",
			"Settlement Currency",
			"Terminal Id",
			"Card Acceptor Id",
			"Card Acceptor Name",
			"Fee Level",
			"Fee Level Sign",
			"Fee Level Desc",
			"Fee Level Ext",
			"Masked Pan",
			"Txn Date Local",
			"Sre Id",
			"Affiliate Code",
			"Cr Dr",
			"Posting Settlement Amount",
			"Narration",
			"Txn Date",
			"Txn Code",
			"Branch",
			"Ccy",
			"Mid",
			"Lcy Amount",
			"Sub Group",
			"Product",
			"Postilion Rrn",
			"Postilion Rrn Resolver",
			"Postilion Rrn Resolved Date",
			"Batch Date",
			"X Rate",
		];

		if (this.props.visaAcquirerTransactions) {
			if (this.props.visaAcquirerTransactions.data.content.length > 0) {
				delete this.props.visaAcquirerTransactions.data.content[0].ep745;
				var columnHeaders = this.props.fileSets.visaAcquirerTransactions.data.content[0];
				var newRows = [ { name: "Action", title: "Action" } ];
				for (var name in columnHeaders) {
					var newObj = {};
					newObj.name = name;
					newObj.title = name;
					newRows.push(newObj);
				}
				var payloadArray = [];
				this.props.visaAcquirerTransactions.data.content.forEach(function (item) {
					if (item.ep745) {
						delete item.ep745;
					}
					payloadArray.push(item);
				});
			}
		}
		// const { defaultHiddenColumnNames } = this.state;

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col>
						{this.props.visaAcquirerTransactions ? (
							<CardGroup className='mb-4'>
								<Widget04
									icon='icon-people'
									color='info'
									header={this.props.visaAcquirerTransactions.data.totalElements.toLocaleString()}
									value='25'
								>
									Transactions
								</Widget04>
								<Widget04 icon='icon-user-follow' color='success' header='0' value='25'>
									Successful Transactions
								</Widget04>
								<Widget04 icon='icon-basket-loaded' color='warning' header='0' value='25'>
									Credits
								</Widget04>
								<Widget04 icon='icon-pie-chart' color='primary' header='0' value='5'>
									Debits
								</Widget04>
								<Widget04 icon='icon-speedometer' color='danger' header='0' value='25'>
									Amount
								</Widget04>
							</CardGroup>
						) : null}
					</Col>
				</Row>
				<Row>
					<Col lg={12}>
						{this.props.fileSets.fileSetFileDefinitionDeleted ? (
							<Alert
								color='success'
								isOpen={this.state.fileSetDeletedAlert}
								toggle={this.onDismissFileSetDeletedSuccessAlert}
							>
								<FormattedMessage
									id='Success: FileSet Deleted Succesfully!'
									defaultMessage='Success: FileSet Deleted Succesfully!'
								/>
							</Alert>
						) : null}
						<Card>
							{/* Manual resolution modal */}
							<ManuallResolutionModal
								updateTransactionType={"acquirer"}
								openModal={this.state.manualResolution}
								transactionData={this.state.selectedItem}
								transactionDate={this.props.match.params.date}
							/>

							<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
								<strong>
									{this.props.visaAcquirerTransactions ? (
										<React.Fragment>Visa Acquirer {this.props.match.params.date}</React.Fragment>
									) : (
										""
									)}
									<FormattedMessage id=' Transactions' defaultMessage=' Transactions' />
								</strong>

								{this.props.visaAcquirerTransactions ? this.props.fileSets.visaAcquirerTransactions.data
									.content.length > 0 ? (
									<div className={"d-flex w-25 justiy-content-between"}>
										<React.Fragment>
											<Input type='select' onChange={this.handleSelect} id='dataType'>
												{this.createSelectItems([
													"ALL",
													"EXCEPTION_POSTILION",
													"EXCEPTION_FLEXCUBE",
													"ZERO_TXN_AMOUNT",
												])}
											</Input>

											<Button
												className={"float-right mb-0 btn-sm btn-block mx-1"}
												color='success'
												onClick={(e) =>
													this.downloadAcquirerTransactions(this.props.match.params.date)}
											>
												<span
													className={"d-flex px-2 justify-content-center align-items-center"}
												>
													<i className='fa fa-download' />&nbsp;
													{this.props.fileSets.download_status ? (
														<Loader
															type='ThreeDots'
															color='#FFF'
															height={30}
															width={30}
															style={{ textAlign: "center" }}
														/>
													) : (
														<FormattedMessage
															id='Download CSV'
															defaultMessage='Download CSV'
														/>
													)}
												</span>
											</Button>
										</React.Fragment>
									</div>
								) : (
									""
								) : (
									""
								)}
							</CardHeader>

							<CardBody>
								{/* Handle Loading */}
								{!this.props.visaAcquirerTransactionsError &&
								!this.props.visaAcquirerTransactions && (
									<Loader
										type='ThreeDots'
										color='#337AB7'
										height={100}
										width={100}
										style={{ textAlign: "center" }}
									/>
								)}

								{/* Handle Errors */}
								{this.props.visaAcquirerTransactions &&
								this.props.visaAcquirerTransactions.data.content.length === 0 && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id='There are no batch transactions at the moment.'
												defaultMessage='There are no batch transactions at the moment.'
											/>
										</p>
									</article>
								)}

								{/* Handle display content */}
								{this.props.visaAcquirerTransactions &&
								this.props.visaAcquirerTransactions.data.content.length > 0 && (
									// Table
									<Table2 hover bordered striped responsive size='sm' style={{ minWidth: "470%" }}>
										<thead>
											<PostingTableHeader
												headerType={"array"}
												headerPayload={VisaIssuerTransactionHeader}
											/>
										</thead>
										<tbody>
											<PostingTable
												tableName={"visa-acquirer-transactions"}
												dataRecords={[ ...payloadArray ]}
											/>
										</tbody>
									</Table2>
								)}
								{this.props.visaAcquirerTransactions &&
								this.props.visaAcquirerTransactions.data.content.length > 0 && (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={20}
											totalItemsCount={
												this.props.visaAcquirerTransactions ? (
													this.props.visaAcquirerTransactions.data.totalElements
												) : null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChange}
										/>
									</nav>
								)}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		fileSets                      : state.fileSets,
		selectedAffiliateCode         : state.fileSets.selectedAffiliateCode,
		visaAcquirerTransactions      : state.fileSets.visaAcquirerTransactions,
		visaAcquirerTransactionsError : state.fileSets.visaAcquirerTransactionsError,
		utils                         : state.utils,
		manualResolution              : state.utils.manualResolution,
		selectedItem                  : state.utils.selectedItem,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchVisaAcquirerTransactions,
			downloadVisaAcquirerCsv,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(VisaAcquirerTransactions);
